head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



scwin.onpageload = function () {
    // 사전 조건은 dataList 정적 데이터로 세팅됨 (추가 처리 없음)
};



// 1 : 옵션 전부 기본값으로 CSV 업로드 (expression 미설정 = "1")
scwin.btn_readCSV_b_onclick = function () {
    grd_expr.readCSV({});
};

// 2 : 동일 GridView 를 expression="0" 으로 호출 (정상 동작 조건 대조)
scwin.btn_readCSV_b_expr0_onclick = function () {
    grd_expr.readCSV({ expression : "0" });
};



// GridView 에 반영된 데이터 Column 값을 한 줄로 출력
scwin.printRows = function (strTag, objGrid, bCalc) {
    var nCnt = objGrid.getRowCount();
    var arrRow = [];

    for (var i = 0; i < nCnt; i++) {
        var v1 = objGrid.getCellData(i, "c1");
        var v2 = objGrid.getCellData(i, "c2");
        var v3 = objGrid.getCellData(i, "c3");
        var strRow = (v1 == null ? "" : v1) + " / " + (v2 == null ? "" : v2) + " / " + (v3 == null ? "" : v3);

        if (bCalc === true) {
            var v4 = objGrid.getCellData(i, 3);
            strRow = strRow + " / calc=" + (v4 == null ? "" : v4);
        }

        arrRow.push("(" + strRow + ")");
    }

    scwin.setReturnValue(strTag + " Row " + nCnt + " : " + arrRow.join(" "));
};

scwin.btn_getResult_onclick = function () {
    scwin.printRows("반영 결과", grd_expr, true);
};
